/**
 * CoolProp WASM Simple API Wrapper
 * 
 * Simplified API for easy integration in any JavaScript application.
 * Provides direct access to PropsSI and AbstractState with automatic initialization.
 */

import Module from './coolprop.js';

let coolpropInstance = null;
let initPromise = null;

/**
 * Initialize CoolProp WASM module (singleton pattern)
 * @returns {Promise<Object>} The initialized CoolProp module
 */
async function ensureInitialized() {
    if (coolpropInstance) {
        return coolpropInstance;
    }
    
    if (initPromise) {
        return initPromise;
    }
    
    initPromise = Module().then(instance => {
        coolpropInstance = instance;
        return instance;
    });
    
    return initPromise;
}

/**
 * PropsSI function - Calculate thermodynamic properties
 * @param {string} output - Output property (e.g., 'T', 'P', 'D', 'H', 'S')
 * @param {string} input1 - First input property name (e.g., 'P', 'T', 'Q')
 * @param {number} value1 - First input value
 * @param {string} input2 - Second input property name
 * @param {number} value2 - Second input value
 * @param {string} fluid - Fluid name (e.g., 'Water', 'CO2', 'Air')
 * @returns {Promise<number>} Property value
 * 
 * @example
 * // Get water density at 300K and 1 atm
 * const density = await PropsSI('D', 'T', 300, 'P', 101325, 'Water');
 * console.log(`Density: ${density} kg/m³`);
 */
export async function PropsSI(output, input1, value1, input2, value2, fluid) {
    const coolprop = await ensureInitialized();
    return coolprop.PropsSI(output, input1, value1, input2, value2, fluid);
}

/**
 * Create AbstractState instance for advanced calculations
 * @param {string} backend - Backend name ('HEOS' for most fluids)
 * @param {string} fluid - Fluid name or mixture
 * @returns {Promise<Object>} AbstractState instance
 * 
 * @example
 * // Create state for water
 * const state = await createAbstractState('HEOS', 'Water');
 * 
 * // Update state to 300K, 1 atm
 * const coolprop = await getCoolProp();
 * state.update(coolprop.input_pairs.PT_INPUTS, 101325, 300);
 * 
 * // Get properties
 * const density = state.rhomass(); // kg/m³
 * const enthalpy = state.hmass();  // J/kg
 */
export async function createAbstractState(backend, fluid) {
    const coolprop = await ensureInitialized();
    return coolprop.factory(backend, fluid);
}

/**
 * Get the initialized CoolProp instance for advanced usage
 * @returns {Promise<Object>} The CoolProp instance
 * 
 * @example
 * const coolprop = await getCoolProp();
 * const PT_INPUTS = coolprop.input_pairs.PT_INPUTS;
 * const iP = coolprop.parameters.iP;
 */
export async function getCoolProp() {
    return await ensureInitialized();
}

/**
 * Initialize CoolProp explicitly (optional - called automatically)
 * @returns {Promise<Object>} The initialized CoolProp module
 */
export async function initCoolProp() {
    return await ensureInitialized();
}

/**
 * Get input pair constants
 * @returns {Promise<Object>} Input pair constants
 */
export async function getInputPairs() {
    const coolprop = await ensureInitialized();
    return coolprop.input_pairs;
}

/**
 * Get parameter constants
 * @returns {Promise<Object>} Parameter constants
 */
export async function getParameters() {
    const coolprop = await ensureInitialized();
    return coolprop.parameters;
}

/**
 * Get phase constants
 * @returns {Promise<Object>} Phase constants
 */
export async function getPhases() {
    const coolprop = await ensureInitialized();
    return coolprop.phases;
}

/**
 * Utility function to create mixtures
 * @param {Array<string>} fluids - Array of fluid names
 * @param {Array<number>} moleFractions - Array of mole fractions
 * @returns {Promise<Object>} AbstractState for mixture
 * 
 * @example
 * // Create air mixture (78% N2, 21% O2, 1% Ar)
 * const air = await createMixture(
 *   ['Nitrogen', 'Oxygen', 'Argon'],
 *   [0.78, 0.21, 0.01]
 * );
 */
export async function createMixture(fluids, moleFractions) {
    if (fluids.length !== moleFractions.length) {
        throw new Error('Fluids and mole fractions arrays must have the same length');
    }
    
    const coolprop = await ensureInitialized();
    const mixture = coolprop.factory('HEOS', fluids.join('&'));
    
    const fractions = new coolprop.VectorDouble();
    moleFractions.forEach(fraction => fractions.push_back(fraction));
    mixture.set_mole_fractions(fractions);
    
    return mixture;
}

// Default export with all functions
export default {
    PropsSI,
    createAbstractState,
    getCoolProp,
    initCoolProp,
    getInputPairs,
    getParameters,
    getPhases,
    createMixture
};